import os
import sys
from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.parse import urlparse, parse_qs

class PreviewServerHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        token = os.getenv('PREVIEW_TOKEN')
        if not token:
            self.send_error(500, "Environment variable PREVIEW_TOKEN is not set")
            return

        auth_header = self.headers.get('Authorization')
        if not auth_header or not auth_header.startswith('Bearer '):
            self.send_error(401, "Unauthorized")
            return

        provided_token = auth_header.split(' ', 1)[1]
        if provided_token != token:
            self.send_error(401, "Unauthorized")
            return

        path = urlparse(self.path).path
        if path != '/preview':
            self.send_error(404, "Not Found")
            return

        query_params = parse_qs(urlparse(self.path).query)
        user = query_params.get('user', ['guest'])[0]
        expr = query_params.get('expr', [''])[0]

        try:
            with open('page.html', 'r', encoding='utf-8') as file:
                content = file.read()

            def replace_user(match):
                return str(user)

            def replace_expr(match):
                try:
                    return str(eval(match.group(0)))
                except:
                    return match.group(0)

            modified_content = content.replace('{{user}}', replace_user('{{user}}'))
            modified_content = modified_content.replace('{{expr}}', replace_expr('{{expr}}'))

            self.send_response(200)
            self.send_header('Content-Type', 'text/html; charset=utf-8')
            self.send_header('Content-Length', str(len(modified_content)))
            self.end_headers()
            self.wfile.write(modified_content.encode('utf-8'))
        except FileNotFoundError:
            self.send_error(404, "Not Found")

def run_server():
    server_address = ('127.0.0.1', 8080)
    httpd = HTTPServer(server_address, PreviewServerHandler)
    print("Server running on http://127.0.0.1:8080")
    httpd.serve_forever()

if __name__ == '__main__':
    run_server()
